PRAGMA foreign_keys = ON;

-- Handbook remediation: post-kickoff background samples are moved into June history; neck/eye observations use score rather than blood pressure.
UPDATE metrics
SET type = CASE WHEN type = 'blood_pressure' AND value_text IS NOT NULL THEN 'score' ELSE type END,
    recorded_at = CASE WHEN recorded_at > '2026-07-01T08:10:00+08:00'
      THEN printf('2026-06-%02dT07:%02d:00+08:00', 1 + ((CAST(substr(metric_id, -4) AS INTEGER) - 1) % 28), CAST(substr(metric_id, -4) AS INTEGER) % 60)
      ELSE recorded_at END,
    value_text = COALESCE(value_text, '')
      || CASE type
        WHEN 'steps' THEN '; source=wearable_daily_total'
        WHEN 'sleep_minutes' THEN '; source=wearable_sleep_summary'
        WHEN 'heart_rate' THEN '; source=wearable_morning_sample'
        ELSE '; source=self_reported_neck_eye_checkin' END
      || '; context=' || CASE (CAST(substr(metric_id, -4) AS INTEGER) % 15)
        WHEN 0 THEN 'basic_class_day' WHEN 1 THEN 'evening_review_day' WHEN 2 THEN 'weekend_long_class' WHEN 3 THEN 'lesson_preparation'
        WHEN 4 THEN 'online_review' WHEN 5 THEN 'classroom_setup' WHEN 6 THEN 'rest_day' WHEN 7 THEN 'short_walk_day'
        WHEN 8 THEN 'eye_break_practice' WHEN 9 THEN 'neck_mobility_practice' WHEN 10 THEN 'parent_meeting_day' WHEN 11 THEN 'teaching_material_day'
        WHEN 12 THEN 'data_gap_review' WHEN 13 THEN 'schedule_change_day' ELSE 'ordinary_teaching_day' END
      || '; handling=' || CASE CAST((CAST(substr(metric_id, -4) AS INTEGER) - 1) / 15 AS INTEGER)
        WHEN 0 THEN 'complete' WHEN 1 THEN 'compare_prior_week' WHEN 2 THEN 'not_training_completion' WHEN 3 THEN 'self_report_labeled'
        WHEN 4 THEN 'no_diagnosis' WHEN 5 THEN 'consider_short_break' WHEN 6 THEN 'consider_deload' WHEN 7 THEN 'cross_check_calendar'
        WHEN 8 THEN 'cross_check_email' WHEN 9 THEN 'private_only' WHEN 10 THEN 'historical_closed' WHEN 11 THEN 'missing_not_imputed'
        WHEN 12 THEN 'screen_exposure_context' WHEN 13 THEN 'board_exposure_context' ELSE 'baseline_context' END
WHERE metric_id LIKE 'metric_gt_%';
UPDATE workouts
SET started_at = CASE WHEN started_at > '2026-07-01T08:10:00+08:00'
  THEN printf('2026-06-%02dT12:%02d:00+08:00', 1 + ((CAST(substr(workout_id, -3) AS INTEGER) - 1) % 28), CAST(substr(workout_id, -3) AS INTEGER) % 60)
  ELSE started_at END;
